/**
 *
 * DataTableHeader renders an optional header slot above the DataTable's table container.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module DataTableHeader
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DataTableRootInstance } from './DataTableRoot.types';
/**
 * Defines passthrough(pt) options type in DataTableHeader component.
 */
export type DataTableHeaderPassThroughType<E> = PassThroughType<DataTableHeaderInstance, E>;
/**
 * Defines passthrough(pt) options of DataTableHeader component.
 */
export interface DataTableHeaderPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: DataTableHeaderPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in DataTableHeader component.
 */
export interface DataTableHeaderProps extends BaseComponentProps<DataTableHeaderInstance, unknown, DataTableHeaderPassThrough> {
}
/**
 * Defines valid state in DataTableHeader component.
 */
export interface DataTableHeaderState {
}
/**
 * Defines the methods and properties exposed by DataTableHeader component.
 */
export interface DataTableHeaderExposes {
    /**
     * The DataTable component instance.
     */
    datatable: DataTableRootInstance | undefined | null;
}
/**
 * Instance of DataTableHeader component.
 */
export type DataTableHeaderInstance = ComponentInstance<DataTableHeaderProps, DataTableHeaderState, DataTableHeaderExposes>;
